examples.template:
MonarchButton({{trigger}}, variant: .secondary) { isPresented = true }
    .sheet(isPresented: $isPresented) {
        MonarchCelebration({{title}}, message: {{description}}, systemImage: "checkmark.circle") {
            MonarchButton({{continue}}, variant: .primary) { isPresented = false }
        }
        .presentationDetents([.medium])
    }

examples.code:
MonarchButton("Show celebration", variant: .secondary) { isPresented = true }
    .sheet(isPresented: $isPresented) {
        MonarchCelebration("Workspace verified", message: "Your public profile now shows the verified badge.", systemImage: "checkmark.circle") {
            MonarchButton("Continue", variant: .primary) { isPresented = false }
        }
        .presentationDetents([.medium])
    }

MonarchButton("Verify") { isVerified = true }
    .sheet(isPresented: $isVerified) {
        MonarchCelebration("Domain verified", message: "Email from acme.com is now signed.") {
            MonarchButton("Continue", variant: .primary, fullWidth: true) { isVerified = false }
        }
        .presentationDetents([.medium])
    }
